## Frontend Implementation

### Core IDE Component

```typescript
// src/components/IDE/IDE.tsx
import React, { useState, useEffect, useRef } from 'react';
import { Editor } from '@monaco-editor/react';
import { Terminal } from 'xterm';
import { WebContainer } from '@webcontainer/api';
import { CerebrasChat } from '../AI/CerebrasChat';
import { FileExplorer } from '../FileExplorer/FileExplorer';

interface IDEProps {
  projectId: string;
  userId: string;
}

export const IDE: React.FC<IDEProps> = ({ projectId, userId }) => {
  const [currentFile, setCurrentFile] = useState<string>('');
  const [fileContent, setFileContent] = useState<string>('');
  const [terminal, setTerminal] = useState<Terminal | null>(null);
  const [webContainer, setWebContainer] = useState<WebContainer | null>(null);
  const [chatVisible, setChatVisible] = useState<boolean>(false);

  const editorRef = useRef<any>(null);
  const terminalRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    initializeWebContainer();
    initializeTerminal();
  }, []);

  const initializeWebContainer = async () => {
    const container = await WebContainer.boot();
    setWebContainer(container);
  };

  const initializeTerminal = () => {
    if (terminalRef.current) {
      const term = new Terminal({
        cursorBlink: true,
        fontSize: 14,
        fontFamily: 'SF Mono, Monaco, Consolas, monospace',
        theme: {
          background: '#1d1d1f',
          foreground: '#ffffff',
        }
      });

      term.open(terminalRef.current);
      setTerminal(term);
    }
  };

  const handleEditorChange = (value: string | undefined) => {
    if (value !== undefined) {
      setFileContent(value);
      // Auto-save functionality
      saveFile(currentFile, value);
    }
  };

  const saveFile = async (fileName: string, content: string) => {
    if (webContainer && fileName) {
      await webContainer.fs.writeFile(fileName, content);
    }
  };

  const runCode = async () => {
    if (webContainer && terminal) {
      const process = await webContainer.spawn('node', [currentFile]);

      process.output.pipeTo(new WritableStream({
        write(data) {
          terminal.write(data);
        }
      }));
    }
  };

  return (
    <div className="ide-container">
      <div className="ide-header">
        <div className="project-info">
          <h2>Project: {projectId}</h2>
          <button onClick={runCode} className="run-button">
            ▶ Run
          </button>
          <button 
            onClick={() => setChatVisible(!chatVisible)}
            className="ai-chat-button"
          >
            🤖 AI Assistant
          </button>
        </div>
      </div>

      <div className="ide-body">
        <div className="file-explorer">
          <FileExplorer 
            webContainer={webContainer}
            onFileSelect={setCurrentFile}
          />
        </div>

        <div className="editor-container">
          <Editor
            ref={editorRef}
            height="60vh"
            defaultLanguage="javascript"
            value={fileContent}
            onChange={handleEditorChange}
            theme="vs-dark"
            options={{
              fontSize: 14,
              fontFamily: 'SF Mono, Monaco, Consolas, monospace',
              automaticLayout: true,
              suggestOnTriggerCharacters: true,
              quickSuggestions: true,
            }}
          />

          <div className="terminal-container">
            <div ref={terminalRef} className="terminal" />
          </div>
        </div>

        {chatVisible && (
          <div className="ai-chat-panel">
            <CerebrasChat projectId={projectId} />
          </div>
        )}
      </div>
    </div>
  );
};
```

### AI Integration Component

```typescript
// src/components/AI/CerebrasChat.tsx
import React, { useState, useEffect } from 'react';
import { Cerebras } from 'cerebras.cloud.sdk';

interface CebrasChatProps {
  projectId: string;
}

export const CerebrasChat: React.FC<CebrasChatProps> = ({ projectId }) => {
  const [messages, setMessages] = useState<Array<{role: string, content: string}>>([]);
  const [input, setInput] = useState<string>('');
  const [isLoading, setIsLoading] = useState<boolean>(false);

  const cerebrasClient = new Cerebras({
    apiKey: process.env.REACT_APP_CEREBRAS_API_KEY
  });

  const sendMessage = async () => {
    if (!input.trim()) return;

    const userMessage = { role: 'user', content: input };
    setMessages(prev => [...prev, userMessage]);
    setInput('');
    setIsLoading(true);

    try {
      const stream = cerebrasClient.chat.completions.create({
        messages: [
          {
            role: 'system',
            content: 'You are an AI coding assistant. Help users with programming questions, code explanations, and debugging. Be concise but helpful.'
          },
          ...messages,
          userMessage
        ],
        model: 'llama-4-maverick-17b-128e-instruct',
        stream: true,
        max_completion_tokens: 32768,
        temperature: 0.6,
        top_p: 0.9
      });

      let assistantResponse = '';
      for await (const chunk of stream) {
        const content = chunk.choices[0]?.delta?.content || '';
        assistantResponse += content;
      }

      setMessages(prev => [...prev, { role: 'assistant', content: assistantResponse }]);
    } catch (error) {
      console.error('Error sending message:', error);
    } finally {
      setIsLoading(false);
    }
  };

  return (
    <div className="cerebras-chat">
      <div className="chat-header">
        <h3>🤖 AI Assistant</h3>
      </div>

      <div className="chat-messages">
        {messages.map((message, index) => (
          <div key={index} className={`message ${message.role}`}>
            <div className="message-content">
              {message.content}
            </div>
          </div>
        ))}
        {isLoading && (
          <div className="message assistant loading">
            <div className="typing-indicator">...</div>
          </div>
        )}
      </div>

      <div className="chat-input">
        <input
          type="text"
          value={input}
          onChange={(e) => setInput(e.target.value)}
          onKeyPress={(e) => e.key === 'Enter' && sendMessage()}
          placeholder="Ask me anything about your code..."
        />
        <button onClick={sendMessage} disabled={isLoading}>
          Send
        </button>
      </div>
    </div>
  );
};
```

