### Code Execution Service

```typescript
// src/server/routes/execution.ts
import { Router } from 'express';
import { Docker } from 'node-docker-api';
import { v4 as uuidv4 } from 'uuid';
import fs from 'fs/promises';
import path from 'path';

const router = Router();
const docker = new Docker({ socketPath: '/var/run/docker.sock' });

// Language configurations
const languageConfigs = {
  javascript: {
    image: 'node:18-alpine',
    cmd: ['node'],
    fileExt: '.js'
  },
  python: {
    image: 'python:3.11-alpine',
    cmd: ['python'],
    fileExt: '.py'
  },
  java: {
    image: 'openjdk:17-alpine',
    cmd: ['java'],
    fileExt: '.java'
  },
  go: {
    image: 'golang:1.19-alpine',
    cmd: ['go', 'run'],
    fileExt: '.go'
  }
};

router.post('/run', async (req, res) => {
  try {
    const { code, language, input = '' } = req.body;
    const config = languageConfigs[language as keyof typeof languageConfigs];

    if (!config) {
      return res.status(400).json({ error: 'Unsupported language' });
    }

    const executionId = uuidv4();
    const tempDir = path.join('/tmp', executionId);
    const fileName = `main${config.fileExt}`;
    const filePath = path.join(tempDir, fileName);

    // Create temporary directory and file
    await fs.mkdir(tempDir, { recursive: true });
    await fs.writeFile(filePath, code);

    // Create and start container
    const container = await docker.container.create({
      Image: config.image,
      Cmd: [...config.cmd, fileName],
      WorkingDir: '/workspace',
      HostConfig: {
        Binds: [`${tempDir}:/workspace`],
        Memory: 128 * 1024 * 1024, // 128MB limit
        CpuShares: 512,
        NetworkMode: 'none' // No network access
      },
      AttachStdout: true,
      AttachStderr: true,
      AttachStdin: true,
      OpenStdin: true,
      StdinOnce: true
    });

    const stream = await container.attach({
      stream: true,
      stdout: true,
      stderr: true,
      stdin: true
    });

    let output = '';
    let error = '';

    stream.on('data', (chunk: Buffer) => {
      const data = chunk.toString();
      if (data.includes('\u0001')) {
        output += data.substring(8); // Remove Docker stream header
      } else if (data.includes('\u0002')) {
        error += data.substring(8);
      }
    });

    await container.start();

    // Send input if provided
    if (input) {
      stream.write(input);
    }

    // Wait for container to finish (with timeout)
    const timeout = setTimeout(async () => {
      await container.kill();
    }, 10000); // 10 second timeout

    await container.wait();
    clearTimeout(timeout);

    // Clean up
    await container.remove();
    await fs.rm(tempDir, { recursive: true, force: true });

    res.json({
      output: output.trim(),
      error: error.trim(),
      executionId
    });

  } catch (error) {
    console.error('Execution error:', error);
    res.status(500).json({ error: 'Execution failed' });
  }
});

export { router as executionRoutes };
```

## Database Schema

```prisma
// prisma/schema.prisma
generator client {
  provider = "prisma-client-js"
}

datasource db {
  provider = "postgresql"
  url      = env("DATABASE_URL")
}

model User {
  id        String   @id @default(cuid())
  email     String   @unique
  username  String   @unique
  name      String?
  avatar    String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  projects Project[]
  collaborations ProjectCollaborator[]

  @@map("users")
}

model Project {
  id          String   @id @default(cuid())
  name        String
  description String?
  language    String
  template    String?
  isPublic    Boolean  @default(false)
  createdAt   DateTime @default(now())
  updatedAt   DateTime @updatedAt

  ownerId String
  owner   User   @relation(fields: [ownerId], references: [id])

  files         File[]
  collaborators ProjectCollaborator[]
  deployments   Deployment[]

  @@map("projects")
}

model File {
  id        String   @id @default(cuid())
  name      String
  path      String
  content   String
  language  String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  projectId String
  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  @@unique([projectId, path])
  @@map("files")
}

model ProjectCollaborator {
  id   String @id @default(cuid())
  role String @default("viewer") // viewer, editor, admin

  projectId String
  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  userId String
  user   User   @relation(fields: [userId], references: [id], onDelete: Cascade)

  createdAt DateTime @default(now())

  @@unique([projectId, userId])
  @@map("project_collaborators")
}

model Deployment {
  id        String   @id @default(cuid())
  url       String?
  status    String   @default("pending") // pending, building, deployed, failed
  buildLogs String?
  createdAt DateTime @default(now())
  updatedAt DateTime @updatedAt

  projectId String
  project   Project @relation(fields: [projectId], references: [id], onDelete: Cascade)

  @@map("deployments")
}
```

