### Deployment Script

```bash
#!/bin/bash
# deploy.sh

set -e

echo "🚀 Deploying AI-Powered Development Platform..."

# Set environment variables
export PROJECT_ID="prime-anvil-460719-s1"
export REGION="us-central1"
export CLUSTER_NAME="dev-platform-cluster"

# Authenticate with GCP
echo "🔐 Authenticating with Google Cloud..."
gcloud auth activate-service-account --key-file=./gcp-service-account.json
gcloud config set project $PROJECT_ID

# Apply Terraform configuration
echo "🏗️ Creating infrastructure..."
cd terraform
terraform init
terraform plan
terraform apply -auto-approve
cd ..

# Get GKE credentials
echo "🔑 Getting GKE credentials..."
gcloud container clusters get-credentials $CLUSTER_NAME --region=$REGION

# Build and push Docker images
echo "🐳 Building and pushing Docker images..."
docker build -t gcr.io/$PROJECT_ID/frontend:latest ./frontend
docker build -t gcr.io/$PROJECT_ID/backend:latest ./backend

docker push gcr.io/$PROJECT_ID/frontend:latest
docker push gcr.io/$PROJECT_ID/backend:latest

# Create Kubernetes secrets
echo "🔒 Creating Kubernetes secrets..."
kubectl create namespace dev-platform --dry-run=client -o yaml | kubectl apply -f -

kubectl create secret generic cerebras-secret \
  --from-literal=api-key=$CEREBRAS_API_KEY \
  --namespace=dev-platform

kubectl create secret generic db-secret \
  --from-literal=url=$DATABASE_URL \
  --namespace=dev-platform

# Apply Kubernetes manifests
echo "☸️ Deploying to Kubernetes..."
kubectl apply -f k8s/

# Wait for deployments
echo "⏳ Waiting for deployments to be ready..."
kubectl wait --for=condition=available --timeout=300s deployment/frontend -n dev-platform
kubectl wait --for=condition=available --timeout=300s deployment/backend -n dev-platform

# Get external IP
echo "🌐 Getting external IP address..."
EXTERNAL_IP=$(kubectl get service frontend-service -n dev-platform -o jsonpath='{.status.loadBalancer.ingress[0].ip}')

echo "✅ Deployment complete!"
echo "🎉 Your development platform is available at: "
echo ""
echo "📋 Next steps:"
echo "1. Configure DNS to point your domain to $EXTERNAL_IP"
echo "2. Set up SSL certificate"
echo "3. Configure OAuth providers for authentication"
```

